    /**
     * Handles loading a Lead using a UUID
     * @param		UUID uuid 
     * @return		Lead
     */    
    @GetMapping("/load")
    public Lead load( @RequestParam(required=true) UUID uuid ) {    	
    	Lead entity = null;

    	try {  
    		entity = service.getLead( new LeadFetchOneSummary( uuid ) );   
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Lead using Id " + uuid );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all Lead business objects
     * @return		Set<Lead>
     */
    @GetMapping("/")
    public List<Lead> loadAll() {                
    	List<Lead> leadList = null;
        
    	try {
            // load the Lead
            leadList = service.getAllLead();
            
            if ( leadList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all Leads" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all Leads ", exc );
        	return null;
        }

        return leadList;
                            
    }

